var daysRe = regexp.MustCompile(`^([+-]?)(\\d+(?:\\.\\d*)?|\\.\\d+)d(.*)$`)

// parseDays parses a duration with a leading days component, such as "30d" or
// "1d12h". A day is 24 hours.
func parseDays(v string) (time.Duration, error) {
	m := daysRe.FindStringSubmatch(v)
	if m == nil {
		return 0, fmt.Errorf("not a duration")
	}
	hours, err := time.ParseDuration(m[2] + "h")
	if err != nil || hours > math.MaxInt64/24 {
		return 0, fmt.Errorf("not a duration")
	}
	d := hours * 24
	if m[3] != "" {
		if m[3][0] == '+' || m[3][0] == '-' {
			return 0, fmt.Errorf("not a duration")
		}
		rest, err := time.ParseDuration(m[3])
		if err != nil || rest > math.MaxInt64-d {
			return 0, fmt.Errorf("not a duration")
		}
		d += rest
	}
	if m[1] == "-" {
		d = -d
	}
	return d, nil
}
